use chrono::{DateTime, Utc};
use std::{collections::{BTreeMap, BTreeSet}, num::NonZeroUsize};
use crate::domain::{models::updates::{EntityUpdate, MonthlyUpdates, RegistrationMonth, UpdatedCompany}, repositories::updates::{UpdatesError, UpdatesRepo}};
/// Complete current-month operation with a request-owned clock instant.
pub trait UpdatesService: Clone + Send + Sync + 'static {
    /// Returns every identity updated in the instant's UTC calendar month.
    fn updates(&self, now: DateTime<Utc>) -> impl Future<Output = Result<MonthlyUpdates, UpdatesError>> + Send;
}
/// Monthly activity application service.
#[derive(Clone)]
pub struct Service<R> { repo: R }
impl<R> Service<R> {
    /// Creates the service.
    pub const fn new(repo: R) -> Self { Self { repo } }
}
struct Activity<I> { identity: I, sources: BTreeSet<i32>, latest: DateTime<Utc> }
fn observe<K: Ord, I>(groups: &mut BTreeMap<K, Activity<I>>, key: K, identity: I, source: i32, date: DateTime<Utc>) {
    let activity = groups.entry(key).or_insert_with(|| Activity { identity, sources: BTreeSet::new(), latest: date });
    activity.sources.insert(source);
    activity.latest = activity.latest.max(date);
}
fn rows<K: Ord, I>(groups: BTreeMap<K, Activity<I>>, name: impl Fn(&I) -> &str) -> Vec<EntityUpdate<I>> {
    let mut rows: Vec<_> = groups.into_iter().collect();
    rows.sort_by(|a, b| b.1.latest.cmp(&a.1.latest).then_with(|| name(&a.1.identity).cmp(name(&b.1.identity))).then_with(|| a.0.cmp(&b.0)));
    rows.into_iter().map(|(_, activity)| EntityUpdate { identity: activity.identity, declaration_count: NonZeroUsize::new(activity.sources.len()).expect("observed activity has a source"), latest_registration: activity.latest }).collect()
}
impl<R: UpdatesRepo> UpdatesService for Service<R> {
    async fn updates(&self, now: DateTime<Utc>) -> Result<MonthlyUpdates, UpdatesError> {
        let month = RegistrationMonth::containing(now);
        let declarations = self.repo.declarations(&month).await?;
        let mut members = BTreeMap::new();
        let mut companies = BTreeMap::new();
        for declaration in declarations {
            if !month.includes(declaration.registered_at) { continue; }
            observe(&mut members, declaration.member.id.value(), declaration.member, declaration.source_id, declaration.registered_at);
            for funder in declaration.funders {
                if !funder.kind.is_individual() {
                    observe(&mut companies, funder.id.value(), UpdatedCompany { id: funder.id, name: funder.name }, declaration.source_id, declaration.registered_at);
                }
            }
        }
        Ok(MonthlyUpdates { month, members: rows(members, |identity| &identity.name), companies: rows(companies, |identity| &identity.name) })
    }
}
