use crate::{domain::{models::updates::{EntityUpdate, MonthlyUpdates}, services::{entity_details::EntityDetailsService, entity_search::EntitySearchService, rankings::RankingsService, updates::UpdatesService}}, inbound::http::{error::ApiError, state::AppState, success::ApiSuccess}};
use axum::{extract::State, http::StatusCode};
use chrono::{DateTime, Utc};
use serde::Serialize;
#[derive(Serialize)]
pub struct UpdateResponse { id: String, name: String, declaration_count: usize, latest_registration: DateTime<Utc> }
#[derive(Serialize)]
pub struct UpdatesResponse { month_start: DateTime<Utc>, month_end: DateTime<Utc>, members: Vec<UpdateResponse>, companies: Vec<UpdateResponse> }
fn response<I>(row: EntityUpdate<I>, identity: impl FnOnce(I) -> (String, String)) -> UpdateResponse {
