                    facts.push(UpdateDeclaration {
                        source_id: source,
                        registered_at: date(if source > 100 { "2026-10-31T23:59:59Z" } else { "2026-10-01T00:00:00Z" }),
                        member: UpdatedMember { id: MemberId::new(id).unwrap(), name: if id < 3 { "Same".into() } else { format!("Member {id:02}") } },
                        funders: vec![UpdateFunder { id: FunderId::new(uuid::Uuid::from_u128(1)), name: "Company".into(), kind: FunderKind::Trust }, UpdateFunder { id: FunderId::new(uuid::Uuid::from_u128(2)), name: "Individual".into(), kind: FunderKind::Individual }],
                    });
                }
            }
            facts.push(UpdateDeclaration { source_id: 999, registered_at: month.end(), member: UpdatedMember { id: MemberId::new(99).unwrap(), name: "Outside".into() }, funders: vec![] });
            Ok(facts)
        }
    }
    #[tokio::test]
    async fn service_counts_distinct_sources_retains_all_identities_and_includes_future_month_dates() {
        let result = Service::new(Repo).updates(date("2026-10-02T12:00:00Z")).await.unwrap();
